effect.shader:
// tempo do Node ligado ao motor (tools/nodevideo/ligar_tempo.py)
#define _cur_time acTime
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _viewport_ratio acProporcaoDoNode
vec4 u_xlat0;
vec4 u_xlat1;
bool u_xlatb1;
vec3 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec3 u_xlat6;
vec3 u_xlat7;
vec3 u_xlat8;
vec2 u_xlat10;
bvec2 u_xlatb10;
float u_xlat11;
vec2 u_xlat18;
vec2 u_xlat20;
vec2 u_xlat21;
float u_xlat27;
bool u_xlatb27;
float u_xlat28;
bool u_xlatb28;
void main()
{
    u_xlat0.xy = acScreenNorm.xy * vec2(_viewport_ratio.x, _viewport_ratio.y);
    u_xlat1.xy = acScreenNorm.xy * vec2(_viewport_ratio.x, _viewport_ratio.y) + vec2(-0.5, -0.5);
    u_xlat1.z = _cur_time * _speed + u_xlat1.y;
    u_xlat18.xy = vec2(_height, _direction) * vec2(0.100000001, 0.0174532942);
    u_xlat2.x = sin(u_xlat18.y);
    u_xlat3.x = cos(u_xlat18.y);
    u_xlat3.y = u_xlat2.x;
    u_xlat27 = dot(u_xlat3.yx, u_xlat1.xz);
    u_xlat27 = u_xlat27 + 0.5;
    u_xlat27 = u_xlat27 / _viewport_ratio.xxxy.w;
    u_xlatb1 = int(_keep_edge)==1;
    if(int(_type) == 0) {
        u_xlat10.x = _width * 0.0500000007;
        u_xlat10.x = u_xlat27 / u_xlat10.x;
        u_xlat10.x = u_xlat10.x + _phase;
        u_xlat10.x = sin(u_xlat10.x);
        u_xlat10.xy = u_xlat10.xx * u_xlat3.xy;
        u_xlat10.xy = u_xlat10.xy * u_xlat18.xx + u_xlat0.xy;
    } else {
        u_xlatb28 = int(_type)==1;
        if(u_xlatb28){
            u_xlat28 = _width * 0.0500000007;
            u_xlat28 = u_xlat27 / u_xlat28;
            u_xlat28 = floor(u_xlat28);
            u_xlat2.x = _phase + 1.5;
            u_xlat28 = u_xlat28 * u_xlat2.x;
            u_xlat28 = fract(u_xlat28);
            u_xlat28 = (-u_xlat28) + 0.25;
            u_xlat2.xy = vec2(u_xlat28) * u_xlat3.xy;
            u_xlat10.xy = u_xlat2.xy * u_xlat18.xx + u_xlat0.xy;
        } else {
            u_xlatb28 = int(_type)==2;
            if(u_xlatb28){
                u_xlat28 = _width * 0.0500000007;
                u_xlat28 = u_xlat27 / u_xlat28;
                u_xlat2.x = fract(u_xlat28);
                u_xlat11 = _phase + 2.0;
                u_xlat2.x = u_xlat2.x * u_xlat11 + -1.0;
                u_xlat2.x = -abs(u_xlat2.x) + 0.5;
                u_xlat28 = floor(u_xlat28);
                u_xlat28 = u_xlat11 * u_xlat28;
                u_xlat28 = fract(u_xlat28);
                u_xlat28 = (-u_xlat28) + 0.5;
                u_xlat28 = u_xlat28 * u_xlat2.x;
                u_xlat2.xy = vec2(u_xlat28) * u_xlat3.xy;
                u_xlat10.xy = u_xlat2.xy * u_xlat18.xx + u_xlat0.xy;
            } else {
                u_xlatb28 = int(_type)==3;
                if(u_xlatb28){
                    u_xlat28 = _width * 0.0500000007;
                    u_xlat28 = u_xlat27 / u_xlat28;
                    u_xlat2.x = _phase + 1.5;
                    u_xlat28 = u_xlat28 * u_xlat2.x;
                    u_xlat28 = fract(u_xlat28);
                    u_xlat28 = (-u_xlat28) + 0.5;
                    u_xlat2.xy = vec2(u_xlat28) * u_xlat3.xy;
                    u_xlat10.xy = u_xlat2.xy * u_xlat18.xx + u_xlat0.xy;
                } else {
                    u_xlatb28 = int(_type)==4;
                    if(u_xlatb28){
                        u_xlat28 = _width * 0.0500000007;
                        u_xlat2.x = u_xlat27 / u_xlat28;
                        u_xlat2.y = _phase;
                        u_xlat28 = dot(u_xlat2.xy, vec2(12.9898005, 78.2330017));
                        u_xlat28 = sin(u_xlat28);
                        u_xlat28 = u_xlat28 * 43758.5469;
                        u_xlat28 = fract(u_xlat28);
                        u_xlat28 = u_xlat28 + -0.5;
                        u_xlat2.xy = vec2(u_xlat28) * u_xlat3.xy;
                        u_xlat10.xy = u_xlat2.xy * u_xlat18.xx + u_xlat0.xy;
                    } else {
                        u_xlatb28 = int(_type)==5;
                        u_xlat2.x = _width * 0.0500000007;
                        u_xlat2.x = u_xlat27 / u_xlat2.x;
                        u_xlat2.y = _phase;
                        u_xlat27 = dot(u_xlat2.xy, vec2(0.366025418, 0.366025418));
                        u_xlat20.xy = vec2(u_xlat27) + u_xlat2.xy;
                        u_xlat20.xy = floor(u_xlat20.xy);
                        u_xlat2.xy = (-u_xlat20.xy) + u_xlat2.xy;
                        u_xlat27 = dot(u_xlat20.xy, vec2(0.211324871, 0.211324871));
                        u_xlat2.xy = vec2(u_xlat27) + u_xlat2.xy;
                        u_xlatb27 = u_xlat2.y<u_xlat2.x;
                        u_xlat4 = u_xlat2.xyxy + vec4(0.211324871, 0.211324871, -0.577350259, -0.577350259);
                        u_xlat5 = (bool(u_xlatb27)) ? vec4(0.0, 1.0, -1.0, -0.0) : vec4(1.0, 0.0, -0.0, -1.0);
                        u_xlat4.xy = u_xlat4.xy + u_xlat5.zw;
                        u_xlat21.xy = u_xlat20.xy * vec2(0.00346020772, 0.00346020772);
                        u_xlat21.xy = floor(u_xlat21.xy);
                        u_xlat20.xy = (-u_xlat21.xy) * vec2(289.0, 289.0) + u_xlat20.xy;
                        u_xlat6.x = float(0.0);
                        u_xlat6.z = float(1.0);
                        u_xlat6.y = u_xlat5.x;
                        u_xlat6.xyz = u_xlat20.yyy + u_xlat6.xyz;
                        u_xlat7.xyz = u_xlat6.xyz * u_xlat6.xyz;
                        u_xlat6.xyz = u_xlat7.xyz * vec3(34.0, 34.0, 34.0) + u_xlat6.xyz;
                        u_xlat7.xyz = u_xlat6.xyz * vec3(0.00346020772, 0.00346020772, 0.00346020772);
                        u_xlat7.xyz = floor(u_xlat7.xyz);
                        u_xlat6.xyz = (-u_xlat7.xyz) * vec3(289.0, 289.0, 289.0) + u_xlat6.xyz;
                        u_xlat6.xyz = u_xlat20.xxx + u_xlat6.xyz;
                        u_xlat5.x = float(0.0);
                        u_xlat5.z = float(1.0);
                        u_xlat5.xyz = u_xlat5.xyz + u_xlat6.xyz;
                        u_xlat6.xyz = u_xlat5.xyz * u_xlat5.xyz;
                        u_xlat5.xyz = u_xlat6.xyz * vec3(34.0, 34.0, 34.0) + u_xlat5.xyz;
                        u_xlat6.xyz = u_xlat5.xyz * vec3(0.00346020772, 0.00346020772, 0.00346020772);
                        u_xlat6.xyz = floor(u_xlat6.xyz);
                        u_xlat5.xyz = (-u_xlat6.xyz) * vec3(289.0, 289.0, 289.0) + u_xlat5.xyz;
                        u_xlat6.x = dot(u_xlat2.xy, u_xlat2.xy);
                        u_xlat6.y = dot(u_xlat4.xy, u_xlat4.xy);
                        u_xlat6.z = dot(u_xlat4.zw, u_xlat4.zw);
                        u_xlat6.xyz = (-u_xlat6.xyz) + vec3(0.5, 0.5, 0.5);
                        u_xlat6.xyz = max(u_xlat6.xyz, vec3(0.0, 0.0, 0.0));
                        u_xlat6.xyz = u_xlat6.xyz * u_xlat6.xyz;
                        u_xlat6.xyz = u_xlat6.xyz * u_xlat6.xyz;
                        u_xlat5.xyz = u_xlat5.xyz * vec3(0.024390243, 0.024390243, 0.024390243);
                        u_xlat5.xyz = fract(u_xlat5.xyz);
                        u_xlat7.xyz = u_xlat5.xyz * vec3(2.0, 2.0, 2.0) + vec3(-1.0, -1.0, -1.0);
                        u_xlat8.xyz = abs(u_xlat7.xyz) + vec3(-0.5, -0.5, -0.5);
                        u_xlat5.xyz = u_xlat5.xyz * vec3(2.0, 2.0, 2.0) + vec3(-0.5, -0.5, -0.5);
                        u_xlat5.xyz = floor(u_xlat5.xyz);
                        u_xlat5.xyz = (-u_xlat5.xyz) + u_xlat7.xyz;
                        u_xlat7.xyz = u_xlat8.xyz * u_xlat8.xyz;
                        u_xlat7.xyz = u_xlat5.xyz * u_xlat5.xyz + u_xlat7.xyz;
                        u_xlat7.xyz = (-u_xlat7.xyz) * vec3(0.853734732, 0.853734732, 0.853734732) + vec3(1.79284286, 1.79284286, 1.79284286);
                        u_xlat6.xyz = u_xlat6.xyz * u_xlat7.xyz;
                        u_xlat27 = u_xlat2.y * u_xlat8.x;
                        u_xlat2.x = u_xlat5.x * u_xlat2.x + u_xlat27;
                        u_xlat21.xy = u_xlat4.yw * u_xlat8.yz;
                        u_xlat2.yz = u_xlat5.yz * u_xlat4.xz + u_xlat21.xy;
                        u_xlat27 = dot(u_xlat6.xyz, u_xlat2.xyz);
                        u_xlat27 = u_xlat27 * 130.0;
                        u_xlat2.xy = vec2(u_xlat27) * u_xlat3.xy;
                        u_xlat18.xy = u_xlat2.xy * u_xlat18.xx + u_xlat0.xy;
                        u_xlat10.xy = (bool(u_xlatb28)) ? u_xlat18.xy : u_xlat0.xy;
                    }
                }
            }
        }
    }
    u_xlat0.xy = u_xlat10.xy / vec2(_viewport_ratio.x, _viewport_ratio.y);
    u_xlatb10.xy = lessThan(u_xlat0.xyxx, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb2.xy = lessThan(vec4(1.0, 1.0, 0.0, 0.0), u_xlat0.xyxx).xy;
    u_xlatb27 = u_xlatb10.x || u_xlatb2.x;
    u_xlatb27 = u_xlatb10.y || u_xlatb27;
    u_xlatb27 = u_xlatb2.y || u_xlatb27;
    u_xlat0.z = (u_xlatb27) ? 0.0 : 1.0;
    u_xlat20.xy = fract(u_xlat0.xy);
    u_xlat20.xy = (-u_xlat20.xy) + vec2(1.0, 1.0);
    u_xlat2.x = (u_xlatb2.x) ? u_xlat20.x : u_xlat0.x;
    u_xlat2.y = (u_xlatb2.y) ? u_xlat20.y : u_xlat0.y;
    {
        vec3 hlslcc_movcTemp = u_xlat2;
        hlslcc_movcTemp.x = (u_xlatb10.x) ? (-u_xlat0.x) : u_xlat2.x;
        hlslcc_movcTemp.y = (u_xlatb10.y) ? (-u_xlat0.y) : u_xlat2.y;
        u_xlat2 = hlslcc_movcTemp;
    }
    u_xlat2.z = 1.0;
    u_xlat0.xyz = (bool(u_xlatb1)) ? u_xlat2.xyz : u_xlat0.xyz;
    u_xlat1 = texture(inputImg, u_xlat0.xy);
    u_xlat0 = u_xlat0.zzzz * u_xlat1;
    if(int(_use_inner_mask) != 0) {
        u_xlat1 = texture(inputImg, acScreenNorm.xy);
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
